import { isTauri } from './Consts';
import { Actions, CollectablesShopRefine, Status } from './Craft';

if (isTauri) {
    // Good, the user is using our Desktop edition. Use the native solvers.
    var pkgTauri = import('@tauri-apps/api/core');
}

export interface Statistics {
    // 发生技能错误的模拟频数
    errors: number;
    // 技能模拟完成后仍处于制作状态的模拟频数
    unfinished: number;
    // 进展未推满的模拟频数
    fails: number;
    // 进展推满，HQ率未达到100%的模拟频数
    normal: number;
    // 进展推满，品质也推满的模拟频数
    highqual: number;
}

export interface CollectableStatistics {
    // 发生技能错误的模拟频数
    errors: number;
    // 技能模拟完成后仍处于制作状态的模拟频数
    unfinished: number;
    // 进展未推满的模拟频数
    fails: number;
    // 无收藏价值
    no_collectability: number;
    // 收藏价值第一档
    low_collectability: number;
    // 收藏价值第二档
    middle_collectability: number;
    // 收藏价值第三档
    high_collectability: number;
}

function runInWorker<T>(
    name: string,
    args: Record<string, unknown>,
): Promise<T> {
    return new Promise((resolve, reject) => {
        const worker = new Worker(
            new URL('./AnalyzerWorker.ts', import.meta.url),
            { type: 'module' },
        );
        worker.onmessage = ev => {
            worker.terminate();
            if (ev.data.error === undefined) resolve(ev.data);
            else reject(ev.data.error);
        };
        worker.onerror = ev => {
            worker.terminate();
            reject(ev);
        };
        worker.postMessage({ name, args: JSON.stringify(args) });
    });
}

export async function rand_simulation(
    status: Status,
    actions: Actions[],
    n: number,
    ignoreErrors: boolean,
): Promise<Statistics> {
    const args = { status, actions, n, ignoreErrors };
    if (isTauri) {
        let { invoke } = await pkgTauri;
        return invoke('rand_simulation', args);
    } else {
        return runInWorker('rand_simulation', args);
    }
}

export async function rand_collectables_simulation(
    status: Status,
    actions: Actions[],
    n: number,
    ignoreErrors: boolean,
    collectablesShopRefine: CollectablesShopRefine,
): Promise<CollectableStatistics> {
    const args = { status, actions, n, ignoreErrors, collectablesShopRefine };
    if (isTauri) {
        let { invoke } = await pkgTauri;
        return invoke('rand_collectables_simulation', args);
    } else {
        return runInWorker('rand_collectables_simulation', args);
    }
}

export interface Scope {
    craftsmanship_range: [number?, number?];
    control_range: number | null;
    craft_points: number;
}

export async function calc_attributes_scope(
    status: Status,
    actions: Actions[],
): Promise<Scope> {
    const args = { status, actions };
    if (isTauri) {
        let { invoke } = await pkgTauri;
        return invoke('calc_attributes_scope', args);
    } else {
        return runInWorker('calc_attributes_scope', args);
    }
}
